def find_segments(column_rows, threshold=1):
    """Find contiguous groups of rows in a column"""
    segments = []
    current_start = None
    current_end = None

    for r in column_rows:
        if current_end is None:
            current_start = current_end = r
        elif r == current_end + 1:
            # Consecutive, extend segment
            current_end = r
        else:
            # New segment
            if current_end - current_start + 1 >= threshold:
                segments.append((current_start, current_end))
            current_start = current_end = r

    if current_end - current_start + 1 >= threshold:
        segments.append((current_start, current_end))

    return segments

