demo_grid = [
    [6]*9,  # row 0
    [1,1,6,1,1,1,6,6,6],  # row 1: {0,1,3,4,5}
    [6,6,6,6,6,1,6,6,6],   # row 2: {5}
    [6,6,6,6,6,1,6,6,6],   # row 3: {5}
    [6,6,6,6,6,1,6,6,6],   # row 4: {5}
    [1,6,6,6,6,6,6,6,6],   # row 5: {0}
    [6,6,6,6,6,1,6,6,6],   # row 6: {5}
    [1,6,6,6,1,1,6,6,6],   # row 7: {0,4,5}
]

output = [row[:] for row in demo_grid]

from collections import defaultdict

# Group by exact column patterns
pattern_to_rows = defaultdict(list)
for r, row in enumerate(demo_grid):
    cols_with_8 = tuple(sorted([c for c in range(9) if row[c] == 1]))
    if len(cols_with_8) >= 1:  # Include even single-point rows!
        pattern_to_rows[cols_with_8].append(r)

print("Pattern groups:")
