        continue

    min_r = min(rows)
    max_r = max(rows)

    min_c = min(pattern)
    max_c = max(pattern)

    print(f"\nDrawing rect for pattern {pattern}: rows {min_r}-{max_r}")

    # Clear interior first
    for r in range(min_r + 1, max_r):
        for c in range(min_c, max_c):
