        output[min_r][c] = new_value
        output[max_r][c] = new_value
    for r in range(min_r + 1, max_r):
        output[r][min_c] = new_value
        output[r][max_c] = new_value

print("\n\nFinal output:")
for i, row in enumerate(output):
